 V('formal register=registro formal|subject line=linha de assunto|courtesy title=título de cortesia|closing phrase=fórmula de despedida|polite request=pedido educado|cross-cultural exchange=intercâmbio intercultural|international colleague=colega internacional|reply deadline=prazo de resposta|email etiquette=etiqueta de e-mail|opening line=frase de abertura|clear purpose=objetivo claro|respectful tone=tom respeitoso|follow-up message=mensagem de acompanhamento|attached file=arquivo anexo|carbon copy=cópia (Cc)|business correspondence=correspondência comercial|concise wording=redação concisa|proofreading habit=hábito de revisão|first impression=primeira impressão|abrupt tone=tom brusco|softening phrase=expressão atenuante|written request=solicitação por escrito|formal salutation=saudação formal|sign-off line=linha de encerramento|cultural expectation=expectativa cultural|reply-all mistake=erro de responder a todos|automatic reply=resposta automática|language formality=formalidade da linguagem'),
 ('Office',[('Ana','Could you check my email to Dr. Tanaka?','Você pode revisar meu e-mail para o Dr. Tanaka?'),('Leo','It is clear, but you could elaborate on the deadline.','Está claro, mas você poderia detalhar o prazo.'),('Ana','Should I start with “Hi”?','Devo começar com “Hi”?'),('Leo','No. Use “Dear Dr. Tanaka” and close with “Yours sincerely”.','Não. Use “Dear Dr. Tanaka” e feche com “Yours sincerely”.')]),
